###############################################################################
# 04b_WGCNA_country_categorical_reviewer_analysis.R
#
# PURPOSE
# Reviewer-facing WGCNA correction after Agustin's comments.
#
# This script DOES NOT rebuild WGCNA.
# It uses the module eigengenes and metadata already generated by Scripts 01–04
# and performs two reviewer-relevant corrections:
#
# 1) Removes Country_numeric from module-trait Spearman correlation outputs.
#    Country should not be treated as a numeric/ordinal trait because it is a
#    categorical recruitment-context variable.
#
# 2) Evaluates country and site/recruitment-context effects categorically:
#      - Kruskal-Wallis tests: module eigengene ~ Country
#      - Adjusted nested linear models:
#            module eigengene ~ Country + diagnosis + age + sex + education
#        compared against:
#            module eigengene ~ diagnosis + age + sex + education
#      - Optional analogous analyses for recruitment site, if detected.
#
# Interpretation:
# - These analyses are internal recruitment-context checks, not external
#   validation and not evidence of country-specific biology.
# - Use these outputs to revise Methods/Results and to remove Country_numeric
#   from module-trait figures/tables.
#
# Expected to be run after:
#   01_define_wgcna_input_from_DEP.R
#   02_wgcna_network_construction.R
#   04_WGCNA_module_trait_clinical_integration.R
#
# Main outputs:
#   results/04b_WGCNA_country_categorical_reviewer/
#     tables/module_trait_results_no_country_numeric.csv
#     tables/module_trait_correlations_no_country_numeric.csv
#     tables/module_trait_fdr_no_country_numeric.csv
#     tables/country_categorical_kruskal_by_module.csv
#     tables/country_categorical_adjusted_lm_by_module.csv
#     tables/country_module_descriptives.csv
#     tables/site_categorical_*.csv              [if site variable detected]
#     tables/reviewer_methods_wording.csv
#     figures/module_trait_heatmap_no_country_numeric.pdf/png
###############################################################################

rm(list = ls())

