###############################################################################
# 03. Helpers
###############################################################################

safe_read_csv <- function(file) {
  if (!file.exists(file)) {
    stop("Missing required file:\n", file, call. = FALSE)
  }
  readr::read_csv(file, show_col_types = FALSE)
}

safe_write_csv <- function(x, file) {
  dir.create(dirname(file), recursive = TRUE, showWarnings = FALSE)
  readr::write_csv(as_tibble(x), file)
}

clean_text_na <- function(x) {
  x <- as.character(x)
  x <- trimws(x)
  x[x %in% c("", "NA", "NaN", "NULL", "null", "N/A", "nan")] <- NA_character_
  x
}

safe_numeric <- function(x) suppressWarnings(as.numeric(x))

standardize_module_name <- function(x) {
  x <- as.character(x)
  x <- trimws(x)
  gsub("^ME", "", x)
}

standardize_metadata_columns <- function(df) {
  rename_map <- c(
    "Mini-SEA" = "Mini_SEA",
    "Mini.SEA" = "Mini_SEA",
    "T-ADLQ" = "T_ADLQ",
    "T.ADLQ" = "T_ADLQ",
    "p-tau181" = "p_tau181",
    "p.tau181" = "p_tau181",
    "p-tau217" = "p_tau217",
    "p.tau217" = "p_tau217",
    "ratio AB42/40" = "ratio_AB42_40",
    "ratio.AB42.40" = "ratio_AB42_40"
  )

  for (old in names(rename_map)) {
    new <- rename_map[[old]]
    if (old %in% names(df) && !new %in% names(df)) {
      names(df)[names(df) == old] <- new
    }
  }

  df
}

encode_basic_variables <- function(df) {
  df <- df %>%
    dplyr::mutate(SampleId = as.character(SampleId))

  if ("SampleGroup" %in% names(df)) {
    df <- df %>%
      dplyr::mutate(
        SampleGroup = as.character(SampleGroup),
        SampleGroup_bin = dplyr::case_when(
          SampleGroup == "CN" ~ 0,
          SampleGroup == "AD" ~ 1,
          TRUE ~ NA_real_
        )
      )
  }

  if ("Sex" %in% names(df)) {
    df <- df %>%
      dplyr::mutate(
        Sex_chr = as.character(Sex),
        Sex_bin = dplyr::case_when(
          Sex_chr %in% c("1", "M", "Male", "male") ~ 0,
          Sex_chr %in% c("2", "F", "Female", "female") ~ 1,
          TRUE ~ safe_numeric(Sex_chr)
        )
      )
  }

  if ("ApoE" %in% names(df) && !"APOE_group" %in% names(df)) {
    df <- df %>%
      dplyr::mutate(
        ApoE = as.character(ApoE),
        APOE_group = dplyr::case_when(
          ApoE %in% c("e2/e4", "e3/e4", "e4/e4") ~ "E4 carrier",
          ApoE %in% c("e2/e2", "e2/e3", "e3/e3") ~ "Non-E4",
          TRUE ~ NA_character_
        )
      )
  }

  if ("APOE_group" %in% names(df) && !"APOE4_carrier" %in% names(df)) {
    df <- df %>%
      dplyr::mutate(
        APOE4_carrier = dplyr::case_when(
          APOE_group == "E4 carrier" ~ 1,
          APOE_group == "Non-E4" ~ 0,
          TRUE ~ NA_real_
        )
      )
  }

  numeric_candidates <- c(
    "Age", "Education", "cdr_global", "cdr_boxscore", "mmse_total",
    "udsfaq_total", "NPI", "Mini_SEA", "T_ADLQ", "p_tau181",
    "p_tau217", "NfL", "ratio_AB42_40", "APOE4_carrier",
    "SampleGroup_bin", "Sex_bin"
  )

  for (cc in intersect(numeric_candidates, names(df))) {
    df[[cc]] <- safe_numeric(df[[cc]])
  }

  # IMPORTANT:
  # We deliberately do NOT create Country_numeric here.
  # Country is kept as a categorical factor.
  if ("Country" %in% names(df)) {
    df <- df %>%
      dplyr::mutate(Country = factor(clean_text_na(Country)))
  }

  df
}

detect_site_variable <- function(df) {
  candidates <- c(
    "Site", "site", "Center", "center", "Cohort", "cohort",
    "RecruitmentSite", "recruitment_site", "site_id", "Site_ID"
  )
  hit <- candidates[candidates %in% names(df)][1]
  if (length(hit) == 0 || is.na(hit)) NA_character_ else hit
}

get_module_colors <- function(modules) {
  modules <- as.character(modules)
  cols <- MODULE_COLORS[modules]
  missing_mods <- modules[is.na(cols)]

  if (length(missing_mods) > 0) {
    extra_cols <- grDevices::rainbow(length(unique(missing_mods)), s = 0.45, v = 0.75)
    names(extra_cols) <- unique(missing_mods)
    cols[is.na(cols)] <- extra_cols[missing_mods]
  }

  names(cols) <- modules
  cols
}

add_sig_stars <- function(q) {
  dplyr::case_when(
    is.na(q) ~ "",
    q < 0.001 ~ "***",
    q < 0.01 ~ "**",
    q < 0.05 ~ "*",
    TRUE ~ ""
  )
}

safe_kruskal <- function(df, outcome, factor_var) {
  d <- df %>%
    dplyr::select(dplyr::all_of(c(outcome, factor_var))) %>%
    tidyr::drop_na()

  if (nrow(d) < MIN_N_FOR_TEST) {
    return(tibble(statistic = NA_real_, p_value = NA_real_, n = nrow(d), n_levels = NA_integer_))
  }

  d[[factor_var]] <- factor(d[[factor_var]])
  n_levels <- nlevels(d[[factor_var]])

  if (n_levels < 2) {
    return(tibble(statistic = NA_real_, p_value = NA_real_, n = nrow(d), n_levels = n_levels))
  }

  kt <- tryCatch(
    stats::kruskal.test(stats::as.formula(paste0(outcome, " ~ ", factor_var)), data = d),
    error = function(e) NULL
  )

  if (is.null(kt)) {
    return(tibble(statistic = NA_real_, p_value = NA_real_, n = nrow(d), n_levels = n_levels))
  }

  tibble(
    statistic = unname(kt$statistic),
    p_value = kt$p.value,
    n = nrow(d),
    n_levels = n_levels
  )
}

safe_adjusted_factor_lm <- function(df, outcome, factor_var, covars = ADJUSTMENT_COVARS) {
  available_covars <- covars[covars %in% names(df)]
  model_vars <- c(outcome, factor_var, available_covars)

  d <- df %>%
    dplyr::select(dplyr::all_of(model_vars)) %>%
    tidyr::drop_na()

  if (nrow(d) < MIN_N_FOR_TEST) {
    return(tibble(
      n = nrow(d),
      n_levels = NA_integer_,
      covariates = paste(available_covars, collapse = ", "),
      p_value_factor = NA_real_,
      partial_R2_factor = NA_real_,
      full_model_adj_R2 = NA_real_
    ))
  }

  d[[factor_var]] <- factor(d[[factor_var]])
  n_levels <- nlevels(d[[factor_var]])

  if (n_levels < 2) {
    return(tibble(
      n = nrow(d),
      n_levels = n_levels,
      covariates = paste(available_covars, collapse = ", "),
      p_value_factor = NA_real_,
      partial_R2_factor = NA_real_,
      full_model_adj_R2 = NA_real_
    ))
  }

  rhs_full <- paste(c(factor_var, available_covars), collapse = " + ")
  rhs_reduced <- if (length(available_covars) > 0) paste(available_covars, collapse = " + ") else "1"

  form_full <- stats::as.formula(paste0(outcome, " ~ ", rhs_full))
  form_reduced <- stats::as.formula(paste0(outcome, " ~ ", rhs_reduced))

  fit_full <- tryCatch(stats::lm(form_full, data = d), error = function(e) NULL)
  fit_reduced <- tryCatch(stats::lm(form_reduced, data = d), error = function(e) NULL)

  if (is.null(fit_full) || is.null(fit_reduced)) {
    return(tibble(
      n = nrow(d),
      n_levels = n_levels,
      covariates = paste(available_covars, collapse = ", "),
      p_value_factor = NA_real_,
      partial_R2_factor = NA_real_,
      full_model_adj_R2 = NA_real_
    ))
  }

  cmp <- tryCatch(stats::anova(fit_reduced, fit_full), error = function(e) NULL)

  if (is.null(cmp) || nrow(cmp) < 2) {
    p_val <- NA_real_
    partial_r2 <- NA_real_
  } else {
    p_val <- cmp$`Pr(>F)`[2]
    rss_reduced <- cmp$RSS[1]
    rss_full <- cmp$RSS[2]
    partial_r2 <- (rss_reduced - rss_full) / rss_reduced
  }

  tibble(
    n = nrow(d),
    n_levels = n_levels,
    covariates = paste(available_covars, collapse = ", "),
    p_value_factor = p_val,
    partial_R2_factor = partial_r2,
    full_model_adj_R2 = summary(fit_full)$adj.r.squared
  )
}

make_factor_descriptives <- function(df, modules, factor_var) {
  purrr::map_dfr(modules, function(m) {
    df %>%
      dplyr::select(dplyr::all_of(c(m, factor_var))) %>%
      tidyr::drop_na() %>%
      dplyr::mutate(Level = as.character(.data[[factor_var]])) %>%
      dplyr::group_by(Level) %>%
      dplyr::summarise(
        Module = m,
        n = dplyr::n(),
        mean_eigengene = mean(.data[[m]], na.rm = TRUE),
        sd_eigengene = sd(.data[[m]], na.rm = TRUE),
        median_eigengene = median(.data[[m]], na.rm = TRUE),
        q25_eigengene = quantile(.data[[m]], 0.25, na.rm = TRUE),
        q75_eigengene = quantile(.data[[m]], 0.75, na.rm = TRUE),
        .groups = "drop"
      ) %>%
      dplyr::select(Module, Level, dplyr::everything())
  })
}

