# 04. Load data
###############################################################################

eig <- safe_read_csv(EIGENGENE_FILE)
meta <- safe_read_csv(META_FILE)

module_trait_original <- if (file.exists(MODULE_TRAIT_FILE)) {
  safe_read_csv(MODULE_TRAIT_FILE)
} else {
  NULL
}

eig <- eig %>%
  dplyr::mutate(SampleId = as.character(SampleId)) %>%
  dplyr::distinct(SampleId, .keep_all = TRUE)

meta <- meta %>%
  standardize_metadata_columns() %>%
  encode_basic_variables() %>%
  dplyr::distinct(SampleId, .keep_all = TRUE)

eig_cols_original <- setdiff(names(eig), "SampleId")
eig_cols_original <- eig_cols_original[!eig_cols_original %in% c("MEgrey", "grey")]

eig_clean <- eig
names(eig_clean)[names(eig_clean) %in% eig_cols_original] <- standardize_module_name(eig_cols_original)

module_cols <- setdiff(names(eig_clean), "SampleId")
module_cols <- module_cols[vapply(eig_clean[module_cols], is.numeric, logical(1))]
module_cols <- setdiff(module_cols, "grey")

analysis_df <- eig_clean %>%
  dplyr::inner_join(meta, by = "SampleId")

for (m in module_cols) {
  analysis_df[[m]] <- safe_numeric(analysis_df[[m]])
}

if (!"Country" %in% names(analysis_df)) {
  stop("Country variable was not found in metadata. Cannot run country categorical analysis.", call. = FALSE)
}

site_var <- detect_site_variable(analysis_df)

safe_write_csv(
  analysis_df,
  file.path(OUT_TABLES, "wgcna_country_categorical_input_clean.csv")
)

###############################################################################
# 05. Remove Country_numeric from module-trait correlation outputs
###############################################################################

if (!is.null(module_trait_original)) {
  module_trait_no_country <- module_trait_original %>%
    dplyr::filter(!Trait %in% c("Country_numeric", "country_numeric", "Country")) %>%
    dplyr::mutate(
      FDR = p.adjust(p_value, method = "BH"),
      stars = add_sig_stars(FDR),
      Trait_label = dplyr::recode(Trait, !!!TRAIT_LABELS, .default = Trait)
    )

  safe_write_csv(
    module_trait_no_country,
    file.path(OUT_TABLES, "module_trait_results_no_country_numeric.csv")
  )

  rho_no_country <- module_trait_no_country %>%
    dplyr::select(Module, Trait, rho) %>%
    tidyr::pivot_wider(names_from = Trait, values_from = rho) %>%
    dplyr::arrange(factor(Module, levels = unique(Module)))

  fdr_no_country <- module_trait_no_country %>%
    dplyr::select(Module, Trait, FDR) %>%
    tidyr::pivot_wider(names_from = Trait, values_from = FDR) %>%
    dplyr::arrange(factor(Module, levels = unique(Module)))

  annot_no_country <- module_trait_no_country %>%
    dplyr::select(Module, Trait, stars) %>%
    tidyr::pivot_wider(names_from = Trait, values_from = stars) %>%
    dplyr::arrange(factor(Module, levels = unique(Module)))

  safe_write_csv(
    rho_no_country,
    file.path(OUT_TABLES, "module_trait_correlations_no_country_numeric.csv")
  )

  safe_write_csv(
    fdr_no_country,
    file.path(OUT_TABLES, "module_trait_fdr_no_country_numeric.csv")
  )

  safe_write_csv(
    annot_no_country,
    file.path(OUT_TABLES, "module_trait_annotations_no_country_numeric.csv")
  )

  # Simple ggplot heatmap without country for reviewer/documentation.
  heatmap_df <- module_trait_no_country %>%
    dplyr::filter(Trait %in% TRAIT_ORDER_NO_COUNTRY) %>%
    dplyr::mutate(
      Trait = factor(Trait, levels = TRAIT_ORDER_NO_COUNTRY),
      Trait_label = dplyr::recode(as.character(Trait), !!!TRAIT_LABELS, .default = as.character(Trait)),
      Trait_label = factor(Trait_label, levels = unname(TRAIT_LABELS[TRAIT_ORDER_NO_COUNTRY[TRAIT_ORDER_NO_COUNTRY %in% names(TRAIT_LABELS)]])),
      Module = factor(Module, levels = unique(Module))
    )

  p_heat <- ggplot2::ggplot(
    heatmap_df,
    ggplot2::aes(x = Trait_label, y = Module, fill = rho)
  ) +
    ggplot2::geom_tile(color = "grey90", linewidth = 0.25) +
    ggplot2::geom_text(ggplot2::aes(label = stars), size = 3) +
    ggplot2::scale_fill_gradient2(
      low = "#6FA8DC",
      mid = "white",
      high = "#F4A08B",
      midpoint = 0,
      limits = c(-0.35, 0.35),
      oob = scales::squish,
      name = "Spearman rho"
    ) +
    ggplot2::labs(
      title = "WGCNA module–trait associations without numerically encoded country",
      x = NULL,
      y = "Module"
    ) +
    ggplot2::theme_bw(base_size = 10) +
    ggplot2::theme(
      panel.grid = ggplot2::element_blank(),
      axis.text.x = ggplot2::element_text(angle = 45, hjust = 1, vjust = 1),
      plot.title = ggplot2::element_text(face = "bold")
    )

  ggplot2::ggsave(
    file.path(OUT_FIGURES, "module_trait_heatmap_no_country_numeric.pdf"),
    p_heat,
    width = 9.5,
    height = 5.5,
    device = grDevices::cairo_pdf
  )

  ggplot2::ggsave(
    file.path(OUT_FIGURES, "module_trait_heatmap_no_country_numeric.png"),
    p_heat,
    width = 9.5,
    height = 5.5,
    dpi = 600,
    bg = "white"
  )
}

###############################################################################
# 06. Country as categorical recruitment-context variable
###############################################################################

country_kruskal <- purrr::map_dfr(module_cols, function(m) {
  safe_kruskal(analysis_df, outcome = m, factor_var = "Country") %>%
    dplyr::mutate(Module = m, factor = "Country", .before = 1)
}) %>%
  dplyr::mutate(FDR = p.adjust(p_value, method = "BH"))

country_lm <- purrr::map_dfr(module_cols, function(m) {
  safe_adjusted_factor_lm(analysis_df, outcome = m, factor_var = "Country") %>%
    dplyr::mutate(Module = m, factor = "Country", .before = 1)
}) %>%
  dplyr::mutate(FDR_factor = p.adjust(p_value_factor, method = "BH"))

country_descriptives <- make_factor_descriptives(
  analysis_df,
  modules = module_cols,
  factor_var = "Country"
) %>%
  dplyr::rename(Country = Level)

safe_write_csv(
  country_kruskal,
  file.path(OUT_TABLES, "country_categorical_kruskal_by_module.csv")
)

safe_write_csv(
  country_lm,
  file.path(OUT_TABLES, "country_categorical_adjusted_lm_by_module.csv")
)

safe_write_csv(
  country_descriptives,
  file.path(OUT_TABLES, "country_module_descriptives.csv")
)

###############################################################################
# 07. Optional recruitment-site categorical analysis
###############################################################################

site_kruskal <- tibble()
site_lm <- tibble()
site_descriptives <- tibble()

if (!is.na(site_var) && site_var %in% names(analysis_df)) {
  analysis_df[[site_var]] <- factor(clean_text_na(analysis_df[[site_var]]))

  site_kruskal <- purrr::map_dfr(module_cols, function(m) {
    safe_kruskal(analysis_df, outcome = m, factor_var = site_var) %>%
      dplyr::mutate(Module = m, factor = site_var, .before = 1)
  }) %>%
    dplyr::mutate(FDR = p.adjust(p_value, method = "BH"))

  site_lm <- purrr::map_dfr(module_cols, function(m) {
    safe_adjusted_factor_lm(analysis_df, outcome = m, factor_var = site_var) %>%
      dplyr::mutate(Module = m, factor = site_var, .before = 1)
  }) %>%
    dplyr::mutate(FDR_factor = p.adjust(p_value_factor, method = "BH"))

  site_descriptives <- make_factor_descriptives(
    analysis_df,
    modules = module_cols,
    factor_var = site_var
  ) %>%
    dplyr::rename(Site = Level)

  safe_write_csv(
    site_kruskal,
    file.path(OUT_TABLES, "site_categorical_kruskal_by_module.csv")
  )

  safe_write_csv(
    site_lm,
    file.path(OUT_TABLES, "site_categorical_adjusted_lm_by_module.csv")
  )

  safe_write_csv(
    site_descriptives,
    file.path(OUT_TABLES, "site_module_descriptives.csv")
  )
}

###############################################################################
# 08. Manuscript-facing notes and methods wording
###############################################################################

reviewer_methods_wording <- tibble::tribble(
  ~section, ~text,
  "Methods - module-trait correlations",
  "Country was not included as a numerically encoded variable in Spearman module–trait correlation matrices because it is a categorical recruitment-context variable rather than an ordinal trait. Module–trait correlations therefore included clinical, cognitive, demographic, genetic and plasma biomarker variables suitable for rank-based correlation analyses.",

  "Methods - recruitment context",
  "Recruitment-context effects were evaluated separately by treating country, and recruitment site when available, as categorical factors. For each module eigengene, we used Kruskal-Wallis tests to compare module eigengene distributions across countries and adjusted nested linear models to quantify country-level variance after accounting for diagnosis, age, sex and education.",

  "Interpretation",
  "Country- and site-level analyses were interpreted as internal recruitment-context sensitivity analyses rather than as evidence of country-specific biology or external validation."
)

safe_write_csv(
  reviewer_methods_wording,
  file.path(OUT_TABLES, "reviewer_methods_wording.csv")
)

analysis_summary <- tibble::tibble(
  item = c(
    "n_samples",
    "n_modules",
    "modules",
    "country_levels",
    "site_variable_detected",
    "site_levels",
    "removed_from_spearman_matrix"
  ),
  value = c(
    as.character(nrow(analysis_df)),
    as.character(length(module_cols)),
    paste(module_cols, collapse = ", "),
    paste(levels(droplevels(analysis_df$Country)), collapse = ", "),
    ifelse(is.na(site_var), "No", site_var),
    ifelse(is.na(site_var), "Not available", paste(levels(droplevels(factor(analysis_df[[site_var]]))), collapse = ", ")),
    "Country_numeric"
  )
)

safe_write_csv(
  analysis_summary,
  file.path(OUT_TABLES, "wgcna_country_categorical_analysis_summary.csv")
)

###############################################################################
# 09. Integrated Excel workbook
###############################################################################

wb_file <- file.path(OUTDIR, "WGCNA_Country_Categorical_Reviewer_Analysis.xlsx")

tables_for_excel <- list(
  Analysis_summary = analysis_summary,
  Methods_wording = reviewer_methods_wording,
  Country_Kruskal = country_kruskal,
  Country_Adjusted_LM = country_lm,
  Country_Descriptives = country_descriptives,
  Site_Kruskal = site_kruskal,
  Site_Adjusted_LM = site_lm,
  Site_Descriptives = site_descriptives
)

if (!is.null(module_trait_original)) {
  tables_for_excel$ModuleTrait_NoCountryNumeric <- module_trait_no_country
}

openxlsx::write.xlsx(
  tables_for_excel,
  file = wb_file,
  overwrite = TRUE
)

message("Done.")
message("Outputs saved to: ", OUTDIR)
message("Main workbook: ", wb_file)
message("Country was treated as categorical; Country_numeric was removed from Spearman module-trait outputs.")
